import { StudioProApi, Microflows } from "@mendix/extensions-api";

export const handleShowMicroflow = async (studioPro: StudioProApi, microflowQualifiedName: string): Promise<void> => {
    if (!microflowQualifiedName) {
        return;
    }

    const [moduleName, microflowName] = microflowQualifiedName.split('.');
    if (!moduleName || !microflowName) {
        return;
    }

    console.log("Showing microflow: " + microflowQualifiedName);

    const microflows: Microflows.Microflow[] = await studioPro.app.model.microflows.loadAll((mf) => mf.moduleName === moduleName && mf.name === microflowName);
    const microflow = microflows[0];
    if (!microflow) {
        const errorMessage = "Could not find microflow.";
        const errorDetails = "This microflow might have been deleted or renamed. Please update the tool microflow selection.";
        return await studioPro.ui.messageBoxes.show(
            "error",
            errorMessage,
            errorDetails
        );
    }
    
    await studioPro.ui.editors.editDocument(microflow.$ID);
};