
import { StudioProApi, SelectorResult } from "@mendix/extensions-api";
import { Tool } from "../../types/tool";

export const handleSelectCustomDocument = async (studioPro: StudioProApi, tool: Tool, fieldName: keyof Tool, elementType?: string): Promise<Tool | null> => {
    const selectorResult: SelectorResult = await studioPro.ui.elementSelectors.selectDocument({
        query: { elementType: elementType }
    });
    if (selectorResult.status == 'ok') {
        const updatedTool: Tool = { ...tool, [fieldName]: selectorResult.selected.module + '.' + selectorResult.selected.name };
        return updatedTool
    }
    return null;
};

export const handleValidateTool = async (field: keyof Tool, tool: Tool): Promise<true | string> => {
    switch (field) {
        case "name":
            if (!tool.name || tool.name.trim() === "") {
                return "Tool name cannot be empty.";
            }
            break;

        case "description":
            if (!tool.description || tool.description.trim() === "") {
                return "Tool description cannot be empty.";
            }
            break;

        case "microflow":
            if (tool.toolType === "Microflow" && (!tool.microflow || tool.microflow.trim() === "")) {
                return "Microflow must be selected for Microflow tool.";
            }
            break;

        case "toolType":
            if (!tool.toolType) {
                return "Tool type cannot be empty.";
            }

        default:
            return true;
    }
    return true;
};